/**
 * normi: hover previews for links generated by the normi plugin.
 *
 * After hovering a normi link for a moment, the target page's body is loaded via
 * DokuWiki's do=export_xhtmlbody (content only, no template/sidebar) and shown in
 * a small popup above the mouse pointer.
 */
jQuery(function () {
    'use strict';

    var OPEN_DELAY = 500;
    var CLOSE_DELAY = 300;
    var GAP = 12;
    var MARGIN = 8;

    // Hover previews make no sense on touch-only devices.
    if (window.matchMedia && window.matchMedia('(hover: none)').matches) {
        return;
    }

    var cache = {};
    var popup = null;
    var openTimer = null;
    var closeTimer = null;
    var currentLink = null;
    var mouse = {x: 0, y: 0};

    function previewUrl(link) {
        var url = new URL(link.href, window.location.href);
        url.hash = '';
        url.searchParams.set('do', 'export_xhtmlbody');
        return url.toString();
    }

    function isCurrentPage(link) {
        var url = new URL(link.href, window.location.href);
        return url.pathname === window.location.pathname && url.search === window.location.search;
    }

    function getPopup() {
        if (!popup) {
            popup = document.createElement('div');
            popup.className = 'normi-preview';
            popup.setAttribute('role', 'tooltip');
            popup.hidden = true;
            popup.addEventListener('mouseenter', function () { clearTimeout(closeTimer); });
            popup.addEventListener('mouseleave', scheduleClose);
            // Inside .dokuwiki so the template's content styles apply.
            (document.querySelector('div.dokuwiki') || document.body).appendChild(popup);
        }
        return popup;
    }

    function load(url) {
        if (!cache[url]) {
            cache[url] = fetch(url, {credentials: 'same-origin'})
                .then(function (r) {
                    if (!r.ok) { throw new Error(r.status); }
                    return r.text();
                })
                .catch(function (e) {
                    delete cache[url];
                    throw e;
                });
        }
        return cache[url];
    }

    function position(el) {
        var vw = document.documentElement.clientWidth;
        var vh = document.documentElement.clientHeight;
        var w = el.offsetWidth;
        var h = el.offsetHeight;

        var left = Math.min(Math.max(mouse.x - w / 2, MARGIN), vw - w - MARGIN);
        var top = mouse.y - h - GAP;
        if (top < MARGIN) {
            // Not enough room above the pointer: show below instead.
            top = Math.min(mouse.y + GAP * 2, vh - h - MARGIN);
        }
        el.style.left = Math.max(left, MARGIN) + 'px';
        el.style.top = Math.max(top, MARGIN) + 'px';
    }

    function show(link) {
        var url = previewUrl(link);
        load(url).then(function (html) {
            if (currentLink !== link) { return; }
            var el = getPopup();
            el.innerHTML = html;
            el.scrollTop = 0;
            el.hidden = false;
            position(el);
        }).catch(function () { /* no preview on error */ });
    }

    function hide() {
        clearTimeout(openTimer);
        currentLink = null;
        if (popup) { popup.hidden = true; }
    }

    function scheduleClose() {
        clearTimeout(closeTimer);
        closeTimer = setTimeout(hide, CLOSE_DELAY);
    }

    document.addEventListener('mouseover', function (e) {
        var link = e.target.closest && e.target.closest('a[data-normi-preview]');
        if (!link) { return; }
        if (link === currentLink) {
            // Pointer came back from the popup to its link: keep it open.
            clearTimeout(closeTimer);
            return;
        }
        // Only existing pages, no nested previews, no self-links.
        if (!link.classList.contains('wikilink1')) { return; }
        if (popup && popup.contains(link)) { return; }
        if (isCurrentPage(link)) { return; }

        clearTimeout(openTimer);
        clearTimeout(closeTimer);
        if (popup) { popup.hidden = true; }
        currentLink = link;
        mouse.x = e.clientX;
        mouse.y = e.clientY;
        openTimer = setTimeout(function () { show(link); }, OPEN_DELAY);
    });

    document.addEventListener('mousemove', function (e) {
        if (currentLink && popup && popup.hidden && currentLink.contains(e.target)) {
            mouse.x = e.clientX;
            mouse.y = e.clientY;
        }
    });

    document.addEventListener('mouseout', function (e) {
        if (!currentLink || !currentLink.contains(e.target)) { return; }
        if (e.relatedTarget && currentLink.contains(e.relatedTarget)) { return; }
        clearTimeout(openTimer);
        if (popup && !popup.hidden) {
            scheduleClose();
        } else {
            currentLink = null;
        }
    });

    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') { hide(); }
    });

    window.addEventListener('scroll', function () {
        if (popup && !popup.hidden && !popup.matches(':hover')) { hide(); }
    }, {passive: true});
});
